                        buffer_init(bb, -1, NULL, b->fbuf, b->flen);
                        ms->offset = offset;
                        ms->eoffset = 0;
                } else {
                        ms->offset = ms->eoffset + offset;
                }
        }
        if ((ms->flags & MAGIC_DEBUG) != 0) {
                fprintf(stderr, "bb=[%p,%" SIZE_T_FORMAT "u,%"
