                    SIZE_T_FORMAT "u,%" SIZE_T_FORMAT "u], [o=%#x, c=%d]\n",
                    bb->fbuf, bb->flen, bb->elen, ms->offset, b->fbuf,
                    b->flen, b->elen, offset, cont_level);
        }
