// acceptRange gives the range of valid values for the second byte in a UTF-8
// sequence.
struct accept_range {
        uint8_t lo; // lowest value for second byte.
        uint8_t hi; // highest value for second byte.
} accept_ranges[16] = {
// acceptRanges has size 16 to avoid bounds checks in the code that uses it.
        { LOCB, HICB },
        { 0xA0, HICB },
        { LOCB, 0x9F },
        { 0x90, HICB },
        { LOCB, 0x8F },
};

protected int
file_looks_utf8(const unsigned char *buf, size_t nbytes, file_unichar_t *ubuf,
    size_t *ulen)
{
        size_t i;
        int n;
        file_unichar_t c;
        int gotone = 0, ctrl = 0;

        if (ubuf)
                *ulen = 0;

        for (i = 0; i < nbytes; i++) {
                if ((buf[i] & 0x80) == 0) {        /* 0xxxxxxx is plain ASCII */
                        /*
                         * Even if the whole file is valid UTF-8 sequences,
                         * still reject it if it uses weird control characters.
                         */

                        if (text_chars[buf[i]] != T)
                                ctrl = 1;

                        if (ubuf)
                                ubuf[(*ulen)++] = buf[i];
                } else if ((buf[i] & 0x40) == 0) { /* 10xxxxxx never 1st byte */
                        return -1;
                } else {                           /* 11xxxxxx begins UTF-8 */
                        int following;
                        uint8_t x = first[buf[i]];
                        const struct accept_range *ar =
                            &accept_ranges[(unsigned int)x >> 4];
                        if (x == XX)
                                return -1;

                        if ((buf[i] & 0x20) == 0) {             /* 110xxxxx */
                                c = buf[i] & 0x1f;
                                following = 1;
                        } else if ((buf[i] & 0x10) == 0) {      /* 1110xxxx */
                                c = buf[i] & 0x0f;
                                following = 2;
                        } else if ((buf[i] & 0x08) == 0) {      /* 11110xxx */
                                c = buf[i] & 0x07;
                                following = 3;
                        } else if ((buf[i] & 0x04) == 0) {      /* 111110xx */
                                c = buf[i] & 0x03;
                                following = 4;
                        } else if ((buf[i] & 0x02) == 0) {      /* 1111110x */
                                c = buf[i] & 0x01;
                                following = 5;
                        } else
                                return -1;

                        for (n = 0; n < following; n++) {
                                i++;
                                if (i >= nbytes)
                                        goto done;

                                if (n == 0 &&
                                     (buf[i] < ar->lo || buf[i] > ar->hi))
                                        return -1;

                                if ((buf[i] & 0x80) == 0 || (buf[i] & 0x40))
                                        return -1;

                                c = (c << 6) + (buf[i] & 0x3f);
                        }

                        if (ubuf)
                                ubuf[(*ulen)++] = c;
                        gotone = 1;
                }
        }
done:
        return ctrl ? 0 : (gotone ? 2 : 1);
}

/*
 * Decide whether some text looks like UTF-8 with BOM. If there is no
 * BOM, return -1; otherwise return the result of looks_utf8 on the
 * rest of the text.
 */
private int
looks_utf8_with_BOM(const unsigned char *buf, size_t nbytes,
    file_unichar_t *ubuf, size_t *ulen)
{
        if (nbytes > 3 && buf[0] == 0xef && buf[1] == 0xbb && buf[2] == 0xbf)
                return file_looks_utf8(buf + 3, nbytes - 3, ubuf, ulen);
        else
                return -1;
}

